import unittest

from solucao import formatar


class TestFormatarComLargura(unittest.TestCase):
    def test_preenche_a_esquerda_com_espacos(self):
        """formatar alinha o numero a direita em 8 posicoes"""
        self.assertEqual(formatar(3.14), "    3.14")

    def test_fixa_duas_casas_decimais(self):
        """formatar completa a segunda casa decimal"""
        self.assertEqual(formatar(42.5), "   42.50")

    def test_numero_inteiro_tambem(self):
        """formatar aceita numero inteiro e formata como decimal"""
        self.assertEqual(formatar(1000), " 1000.00")
